// Hand-written service worker -- see RegisterServiceWorker for why this
// isn't generated by next-pwa/@ducanh2912/next-pwa: both only hook into
// webpack's config, and this project's `next dev`/`next build` run on
// Turbopack (the default bundler for this Next version), which never calls
// a webpack() config function at all. Installing either package would add a
// dependency that silently does nothing.
//
// Caching here is deliberately conservative: this is a load board, so HTML
// documents and API responses are never cached (a stale load list is a real
// bug), only same-origin static image/icon assets get a cache-first
// strategy. That's the extent of "caching" a hand-rolled worker can safely
// do without a build-time precache manifest.
const STATIC_CACHE = "heavyhaul-static-v1";
const STATIC_PATH_RE = /^\/(icon-|logo-|favicon\.ico)/;

self.addEventListener("install", () => {
  self.skipWaiting();
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) =>
        Promise.all(keys.filter((key) => key !== STATIC_CACHE).map((key) => caches.delete(key)))
      )
      .then(() => self.clients.claim())
  );
});

self.addEventListener("fetch", (event) => {
  const url = new URL(event.request.url);
  if (event.request.method !== "GET" || url.origin !== self.location.origin) return;
  if (!STATIC_PATH_RE.test(url.pathname)) return;

  event.respondWith(
    caches.open(STATIC_CACHE).then(async (cache) => {
      const cached = await cache.match(event.request);
      if (cached) return cached;
      const response = await fetch(event.request);
      if (response.ok) cache.put(event.request, response.clone());
      return response;
    })
  );
});

// Separate channel from SMS/email -- this is the only place a push message
// actually becomes a system notification. Payload shape is whatever
// sendPushNotification (src/lib/web-push.ts) JSON.stringifies.
self.addEventListener("push", (event) => {
  let data = { title: "HeavyHaul Escort Loads", body: "You have a new load match.", url: "/" };
  if (event.data) {
    try {
      data = { ...data, ...event.data.json() };
    } catch {
      data.body = event.data.text();
    }
  }

  event.waitUntil(
    self.registration.showNotification(data.title, {
      body: data.body,
      icon: "/icon-192.png",
      badge: "/icon-192.png",
      data: { url: data.url },
    })
  );
});

self.addEventListener("notificationclick", (event) => {
  event.notification.close();
  const url = event.notification.data?.url || "/";
  event.waitUntil(
    self.clients.matchAll({ type: "window", includeUncontrolled: true }).then((clients) => {
      for (const client of clients) {
        if (client.url === url && "focus" in client) return client.focus();
      }
      return self.clients.openWindow(url);
    })
  );
});
